9	/**
10	 * Rejects a create once 100 or more owners have already been registered today, counted
11	 * by {@link Owner#getRegistrationDate()} against the server's current date. Runs before
12	 * the owner is saved, so the count excludes the owner being created; a full day is
13	 * rejected 429 via {@link DailyRegistrationLimitException}.
14	 */
15	public class EnsureDailyRegistrationLimit {
16	
17	    /** Maximum number of owners that may be registered on a single day. */
18	    private static final int DAILY_LIMIT = 100;
19	
20	    public void service(OwnerRepository ownerRepository) throws DailyRegistrationLimitException {
21	        LocalDate today = LocalDate.now();
22	        int count = 0;
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (today.equals(existing.getRegistrationDate())) {
25	                count++;
26	            }
27	        }
28	        if (count >= DAILY_LIMIT) {
29	            throw new DailyRegistrationLimitException(today, count);
30	        }
31	    }
32	}
