20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", expression = "java(toDisplayName(owner))")
23	    @Mapping(target = "initials", expression = "java(toInitials(owner))")
24	    @Mapping(target = "membershipTier", expression = "java(toMembershipTier(owner))")
25	    @Mapping(target = "locality", expression = "java(toLocality(owner))")
26	    OwnerDto toOwnerDto(Owner owner);
27	
28	    /** City -> canonical region; anything not listed derives locality 'UNKNOWN'. */
29	    Map<String, String> CITY_REGION = Map.of(
30	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
31	
32	    /**
33	     * The owner's locality, derived from the city using a fixed city-to-region table
34	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD), or 'UNKNOWN' when the city is not
35	     * in the table.
36	     */
37	    default String toLocality(Owner owner) {
38	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
39	    }
40	
41	    /**
42	     * The owner's membership tier: 'SILVER' when namesakeCount is 0 and an email is
43	     * present, otherwise 'BRONZE'.
44	     */
45	    default OwnerDto.MembershipTierEnum toMembershipTier(Owner owner) {
46	        Integer namesakeCount = owner.getNamesakeCount();
47	        String email = owner.getEmail();
48	        boolean hasEmail = email != null && !email.isBlank();
49	        return (namesakeCount != null && namesakeCount == 0 && hasEmail)
50	                ? OwnerDto.MembershipTierEnum.SILVER : OwnerDto.MembershipTierEnum.BRONZE;
51	    }
52	
53	    /** The owner's name formatted as 'LastName, FirstName'. */
54	    default String toDisplayName(Owner owner) {
55	        return owner.getLastName() + ", " + owner.getFirstName();
56	    }
57	
58	    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot. */
59	    default String toInitials(Owner owner) {
60	        return owner.getFirstName().substring(0, 1).toUpperCase()
61	                + "." + owner.getLastName().substring(0, 1).toUpperCase() + ".";
62	    }
63	
64	    Owner toOwner(OwnerDto ownerDto);
65	
66	    @Mapping(target = "id", ignore = true)
67	    @Mapping(target = "pets", ignore = true)
68	    @Mapping(target = "customerCode", ignore = true)
69	    @Mapping(target = "householdId", ignore = true)
70	    @Mapping(target = "namesakeCount", ignore = true)
71	    @Mapping(target = "membershipNumber", ignore = true)
72	    Owner toOwner(OwnerFieldsDto ownerDto);
73	
74	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
75	
76	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
77	
78	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
79	        OwnerPageDto ownerPageDto = new OwnerPageDto();
80	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
81	        ownerPageDto.setPage(ownerPage.getNumber());
