1	package org.springframework.samples.petclinic.rest.escalation;
2	
3	import java.time.LocalDate;
4	
5	/**
6	 * Thrown when creating an owner once 100 or more owners have already been registered
7	 * today (by registration date). Handled globally by
8	 * {@link DailyRegistrationLimitExceptionHandler}, which responds 429.
9	 */
10	public class DailyRegistrationLimitException extends Exception {
11	
12	    private final LocalDate date;
13	
14	    private final int count;
15	
16	    public DailyRegistrationLimitException(LocalDate date, int count) {
17	        super("The daily registration limit has been reached: " + count
18	                + " owners were already registered on " + date);
19	        this.date = date;
20	        this.count = count;
21	    }
22	
23	    /** The registration date that has reached its limit. */
24	    public LocalDate getDate() {
25	        return this.date;
26	    }
27	
28	    /** The number of owners already registered on that date. */
29	    public int getCount() {
30	        return this.count;
31	    }
32	}
