9	public class DailyRegistrationLimitExceptionHandler {
10	
11	    public void handle(@Parameter DailyRegistrationLimitException ex,
12	            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
13	        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.TOO_MANY_REQUESTS, ex.getMessage());
14	        detail.setProperty("date", ex.getDate().toString());
15	        detail.setProperty("count", ex.getCount());
16	        response.send(ResponseEntity.status(HttpStatus.TOO_MANY_REQUESTS).body(detail));
17	    }
18	}
